INSERT INTO feature VALUES('buffer-tokens','sessions','Buffer tokens','session-types','partial','notable',NULL,'A linear buffer token, placed live by a receive or by `std.io.Ring.alloc` and returned exactly once, by every arm of a case or by none; reading the area at a buffer is the next rung.','core-checker','corpus/model/completion/buffer-returned.gandr','corpus/ledger/features/buffer-tokens.gandr','#1263 #1184');
